-- Resources content for Ask WUWF and Host requests (CLAUDE.md, "Resources stay in step with the code"). Content only; no schema.
-- The prefix continues the sequence past 20261110120000; see 20261103120000's header on why a prefix is a sequence number.
--
-- What changed for a reader: Audience Listening gained two pages beside the list of queries, Ask WUWF and Host requests, with a
-- count of what is waiting. The guide is new rather than an edit of an existing one so an editor's changes to those are not touched.

select private.rc_release_guide(
  p_slug => 'audience-listening-ask-wuwf-and-host-requests',
  p_tool_key => 'audience-listening',
  p_title => 'Ask WUWF and host requests',
  p_summary => 'Read what people send from the website, mark where each has got to, and keep to the week the website promises.',
  p_screen_keys => array['audience-listening.inboxes'],
  p_sort_order => 40,
  p_version_note => 'Ask WUWF and Host requests',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The website has two places where someone can write to the station without answering a query and without an account: "},{"type":"text","text":"Ask WUWF","marks":[{"type":"bold"}]},{"type":"text","text":", for a question or a story idea, and a request to host a listening session. Both arrive here, under "},{"type":"text","text":"Ask WUWF","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Host requests","marks":[{"type":"bold"}]},{"type":"text","text":" beside the list of queries. A person reads every one."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Ask WUWF"}]},{"type":"paragraph","content":[{"type":"text","text":"Each message shows what was sent, when, and whether it is a question or a story idea. If the sender left an email it appears as a link, because they asked to hear what came of it. If they did not, there is no one to write back to."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set "},{"type":"text","text":"Where it stands","marks":[{"type":"bold"}]},{"type":"text","text":" to Read, Answered or Not used, and add a private note. The note is for staff and never appears on the website."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing here promises a reply or a date. If you write back, say only what the station will do."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Delete removes the message and any email with it, for good. Use it for spam or anything that should not be kept."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Host requests"}]},{"type":"paragraph","content":[{"type":"text","text":"A request comes from the form for bringing a listening session to a table. It shows who asked, when they have in mind, where, how many seats, how many people they expect, who they would invite, and whether they asked for a WUWF journalist to join. The email is a link so you can write back."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The website tells the person that someone will write back within a week. The oldest requests are at the top, and a request still marked New after five days is flagged, with a notice above the list."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark a request Contacted once you have written, Scheduled once a date is agreed, or Declined. Add a private note for what you said."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scheduling here records only the state. Events and tables are set up separately, once they are added to the Portal."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Neither list shows who the sender was on the website. The Portal does not keep the visitor behind a message."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Needs a person view shows what is new or still open. Use the other views to look back at what has been answered."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing is emailed to staff yet. Check the counts beside Ask WUWF and Host requests in the section's navigation."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-11-10-audience-listening-inboxes',
  p_tool_key => 'audience-listening',
  p_released_on => '2026-11-10',
  p_title => 'Ask WUWF and host requests arrive in Audience Listening',
  p_guide_slugs => array['audience-listening-ask-wuwf-and-host-requests'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Audience Listening has two new pages beside the list of queries. Ask WUWF holds the questions and story ideas people send from the website, and Host requests holds the requests to bring a listening session to a table. Each can be marked Read, Answered or Not used (or Contacted, Scheduled or Declined for a request), with a private note. Host requests are listed oldest first, and any still new after five days are flagged, because the website promises an answer within a week. Nothing is emailed to staff yet, so the counts in the section's navigation are the way to see what is waiting."}]}]}$body$
);
